import {Component, OnInit} from '@angular/core';
import {ActivatedRoute} from '@angular/router';
import {Title} from '@angular/platform-browser';
import {AppConstants} from '../constants/app.constants';
import {FormService} from '../service/form.service';
import {AuthService} from '../auth/auth.service';

@Component({
    selector: 'app-thanks-component',
    templateUrl: './thanks.component.html',
    styleUrls: ['./thanks.component.scss']
})
export class ThanksComponent implements OnInit {

    pdfurl = '';
    reference: string = '';
    formTitle: string = '';
    uuid: string = '';

    constructor(public route: ActivatedRoute,
                private titleService: Title,
                private formService: FormService,
                private authService: AuthService
    ) {
        this.route.queryParams
            .subscribe(params => {
                this.reference = params.reference;
                this.formTitle = params.formTitle;
                this.uuid = params.uuid
            });
    }

    ngOnInit(): void {
        this.titleService.setTitle(AppConstants.TITLE_PREFIX + 'Bedankt');
        const secured = this.authService.isAuthenticated();
        this.pdfurl = this.formService.getPdfUrl(secured, this.uuid, this.reference, this.formTitle)
    }

    public openPDF(pdfUrl: string): void {
        window.open(pdfUrl);
    }

    getCallbackUrl(): string {
        return this.formService.getCallbackUrl();
    }
}
