import { Component, OnInit } from '@angular/core';
import { Title } from '@angular/platform-browser';
import { ActivatedRoute } from '@angular/router';
import { getConfig } from '../app-config';
import { AppConstants } from '../constants/app.constants';

@Component({
    selector: 'app-paymentsuccess-component',
    templateUrl: './paymentsuccess.component.html',
    styleUrls: ['./paymentsuccess.component.scss']
})
export class PaymentSuccessComponent implements OnInit  {
    reference = '';

    constructor(public route: ActivatedRoute,
                private titleService: Title) {
        this.route.queryParams
            .subscribe(params => {
                return this.reference = params.reference;
            });
    }

    ngOnInit(): void {
        this.titleService.setTitle(AppConstants.TITLE_PREFIX + 'Bedankt geslaagd');
    }

    back(): void {
        window.location.href = getConfig().defaultCallbackUrl;
    }
}
